"""
title: Ollama Usage Monitor
author: Johannes Faber (FAI-Solutions)
website: https://FAI-Solutions.github.io
open-webui_extension_hub: https://github.com/FAI-Solutions/open-webui-extensions
openwebui_id: 8b79ffd1-640d-4b43-b816-cc0071eb4e3b
description: Shows Ollama Cloud usage stats (session/weekly + models used this week) as an embed above each LLM response. Detailed setup in github-repo: https://github.com/FAI-Solutions/open-webui-extensions/tree/main/ollama-usage-monitor
requirements: cloudscraper
version: 1.0
"""

import asyncio
import json
import time
import html as html_mod
from typing import Optional, Callable, Dict, List
from dataclasses import dataclass, field
from pydantic import BaseModel, Field
import cloudscraper

# Data class for parsed usage
@dataclass
class ModelUsage:
    """A single model's weekly request count."""
    name: str
    requests: str = ""


@dataclass
class UsageData:
    """Parsed usage data from Ollama Cloud"""
    session_percent: str = "N/A"
    session_reset: str = "N/A"
    weekly_percent: str = "N/A"
    weekly_reset: str = "N/A"
    weekly_models: List[ModelUsage] = field(default_factory=list)
    error_message: str = ""

    def format_compact(self) -> str:
        """Format usage data in compact form."""
        if self.error_message:
            return f"Error: {self.error_message}"

        weekly_pct = self.weekly_percent.replace(" used", "")
        session_pct = self.session_percent.replace(" used", "")
        weekly_reset = self.weekly_reset.replace("Resets in ", "")
        session_reset = self.session_reset.replace("Resets in ", "")

        return (
            f"Weekly {weekly_pct} → Reset {weekly_reset} • "
            f"Session {session_pct} → Reset {session_reset}"
        )


# Ollama usage client (cloudscraper-based)
class OllamaUsageClient:
    """Fetches Ollama Cloud usage stats via cloudscraper, bypassing Cloudflare"""
    BASE_URL = "https://ollama.com/settings"

    def __init__(
        self,
        name: str = "",
        secure_session: str = "",
        aid: str = "",
        cf_clearance: Optional[str] = None,
        debug: bool = False,
    ):
        self.name = name
        self.secure_session = secure_session
        self.aid = aid
        self.cf_clearance = cf_clearance
        self.debug = debug

        self.scraper = cloudscraper.create_scraper()
        self._setup_cookies()

    def _log(self, msg: str):
        """Print debug message if debug mode is enabled."""
        if self.debug:
            print(f"DEBUG [client:{self.name}]: {msg}")

    def _setup_cookies(self):
        """Configure cookies for the session."""
        cookies = {
            "__Secure-session": self.secure_session,
            "aid": self.aid,
        }
        if self.cf_clearance:
            cookies["cf_clearance"] = self.cf_clearance

        if hasattr(self.scraper, "cookies"):
            self.scraper.cookies.update(cookies)

    def fetch_usage(self) -> UsageData:
        """Fetch usage data from the Ollama settings page."""
        start = time.monotonic()
        try:
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
            }

            response = self.scraper.get(self.BASE_URL, headers=headers, timeout=15)
            response.raise_for_status()

            self._log(f"Response status: {response.status_code}")

            # Check for Cloudflare challenge page
            if (
                "Just a moment" in response.text
                or "cf-browser-verification" in response.text
            ):
                self._log("Cloudflare challenge detected")
                return UsageData(
                    error_message="Cloudflare challenge still active - need fresh cf_clearance"
                )

            data = self._parse_html(response.text)
            self._log(f"Fetch completed in {time.monotonic() - start:.2f}s")
            return data

        except Exception as e:
            self._log(
                f"Fetch error after {time.monotonic() - start:.2f}s: "
                f"{type(e).__name__}: {str(e)[:100]}"
            )
            return UsageData(
                error_message=f"Fetch error: {type(e).__name__}: {str(e)[:50]}"
            )

    def _parse_html(self, html: str) -> UsageData:
        """Extract usage data from the settings page HTML."""
        try:
            from bs4 import BeautifulSoup
        except ImportError:
            return UsageData(error_message="BeautifulSoup not available")

        soup = BeautifulSoup(html, "html.parser")
        data = UsageData()

        # Find the "Cloud usage" heading
        all_h2 = [h.get_text(strip=True) for h in soup.find_all("h2")]
        self._log(f"All h2 tags: {all_h2}")

        cloud_usage = None
        for h2 in soup.find_all("h2"):
            if "Cloud usage" in h2.get_text():
                cloud_usage = h2
                break

        if not cloud_usage:
            page_title = soup.title.get_text() if soup.title else "No title"
            self._log(f"Cloud Usage h2 NOT found. Page title: {page_title}")
            return UsageData(
                error_message=f"Cloud Usage h2 not found. Page title: {page_title}"
            )

        # Parse usage percentage divs
        usage_divs = soup.find_all("div", class_="flex justify-between mb-2")
        self._log(f"Found {len(usage_divs)} usage divs")

        for div in usage_divs:
            spans = div.find_all("span")
            if len(spans) >= 2:
                label = spans[0].get_text(strip=True)
                value = spans[1].get_text(strip=True)
                self._log(f"Usage div - label: '{label}', value: '{value}'")
                if label == "Session usage":
                    data.session_percent = value
                elif label == "Weekly usage":
                    data.weekly_percent = value

        # Parse reset time divs
        time_divs = soup.find_all("div", class_="local-time")
        self._log(f"Found {len(time_divs)} time divs")

        reset_times = []
        for div in time_divs:
            text = div.get_text(strip=True)
            reset_times.append(text)
            self._log(f"Time div - text: '{text}'")

        if len(reset_times) >= 1:
            data.session_reset = reset_times[0]
        if len(reset_times) >= 2:
            data.weekly_reset = reset_times[1]

        # Parse weekly model usage
        models_container = soup.find("div", id="weekly-usage-models")
        if models_container:
            for row in models_container.find_all(
                "div",
                class_=lambda c: c
                and "flex" in c
                and "min-w-0" in c
                and "items-center" in c
                and "gap-2" in c,
            ):
                spans = row.find_all("span")
                if len(spans) < 3:
                    continue
                name = spans[1].get("title") or spans[1].get_text(strip=True)
                requests = spans[2].get_text(strip=True)
                if name:
                    data.weekly_models.append(ModelUsage(name=name, requests=requests))
                    self._log(f"Weekly model: '{name}' -> {requests}")
        else:
            self._log("No weekly-usage-models block (no models used this week)")

        self._log(f"Parsed: {data.format_compact()}")
        return data


# Embed HTML builder
def _esc(text) -> str:
    return html_mod.escape(str(text), quote=True)


def _build_embed(accounts: List[Dict]) -> str:
    """Build the sandboxed iframe card. `accounts` is a list of dicts with
    keys: name, data (UsageData). Renders one expandable row per account."""

    rows = ""
    for acc in accounts:
        name = _esc(acc["name"])
        d: UsageData = acc["data"]

        if d.error_message:
            rows += (
                f'<details class="acc"><summary>'
                f'<span class="an">{name}</span>'
                f'<span class="as err">{_esc(d.error_message)}</span>'
                f"</summary></details>\n"
            )
            continue

        stats = _esc(d.format_compact())

        # Weekly model breakdown (expandable body)
        if d.weekly_models:
            model_rows = "".join(
                f'<div class="mrow"><span class="mname">{_esc(m.name)}</span>'
                f'<span class="mreq">{_esc(m.requests)}</span></div>'
                for m in d.weekly_models
            )
        else:
            model_rows = '<div class="mrow"><span class="mname dim">No models used this week</span></div>'

        rows += (
            f'<details class="acc"><summary>'
            f'<span class="an">{name}</span>'
            f'<span class="as">{stats}</span>'
            f"</summary>"
            f'<div class="abody">'
            f'<div class="mhead">Models used this week</div>'
            f"{model_rows}"
            f"</div></details>\n"
        )

    return f"""<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
*{{box-sizing:border-box;margin:0;padding:0}}
body{{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;font-size:13px;background:#0f1117;color:#e4e6eb;line-height:1.45}}
@media(prefers-color-scheme:light){{body{{background:#f5f6fa;color:#1a1d27}}}}
#app{{padding:10px 14px}}
.hdr{{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:8px}}
.hdr .t{{font-size:11px;font-weight:700;color:#6c8cff}}
.hdr .t small{{font-weight:400;color:#a0a4b0;font-size:.85em}}
.hdr a{{font-size:10px;color:#6c8cff;text-decoration:none}}
.hdr a:hover{{text-decoration:underline}}
details.acc{{background:#1a1d27;border:1px solid #252830;border-radius:8px;margin-bottom:6px;overflow:hidden}}
@media(prefers-color-scheme:light){{details.acc{{background:#fff;border-color:#ecedf1}}}}
details.acc>summary{{cursor:pointer;list-style:none;display:flex;align-items:center;gap:8px;padding:8px 12px;user-select:none}}
details.acc>summary::-webkit-details-marker{{display:none}}
details.acc>summary::before{{content:'▸';color:#6c8cff;transition:transform .15s;flex:none}}
details.acc[open]>summary::before{{transform:rotate(90deg)}}
details.acc>summary:hover{{background:#252830}}
@media(prefers-color-scheme:light){{details.acc>summary:hover{{background:#ecedf1}}}}
.an{{font-weight:600;flex:none}}
.as{{color:#a0a4b0;font-size:12px;word-break:break-word}}
.as.err{{color:#ff6b6b}}
.abody{{padding:2px 12px 10px 30px}}
.mhead{{font-size:10px;font-weight:700;color:#a0a4b0;text-transform:uppercase;letter-spacing:.04em;margin-bottom:4px}}
.mrow{{display:flex;justify-content:space-between;gap:10px;padding:2px 0;font-size:12px;border-bottom:1px solid #252830}}
.mrow:last-child{{border-bottom:none}}
@media(prefers-color-scheme:light){{.mrow{{border-color:#ecedf1}}}}
.mname{{word-break:break-all}}
.mname.dim{{color:#a0a4b0}}
.mreq{{color:#a0a4b0;flex:none;font-variant-numeric:tabular-nums}}
</style></head><body>
<div id="app">
<div class="hdr"><span class="t">☁ Ollama Usage Monitor <small>v1.0</small></span>
<a href="https://github.com/FAI-Solutions/open-webui-extensions" target="_blank" rel="noopener">FAI-Solutions Open WebUI Extensions Hub&nbsp;↗</a></div>
{rows}
</div>
<script>
function rh(){{try{{var el=document.getElementById('app');var h=el?el.getBoundingClientRect().height:document.body.scrollHeight;parent.postMessage({{type:'iframe:height',height:Math.ceil(h)}},'*')}}catch(e){{}}}}
document.querySelectorAll('details.acc').forEach(d=>{{d.addEventListener('toggle',rh)}});
window.addEventListener('load',rh);
if(window.ResizeObserver){{new ResizeObserver(rh).observe(document.getElementById('app')||document.body)}}
rh();
</script>
</body></html>"""


# Open WebUI Filter
class Filter:
    """Open WebUI Filter for monitoring Ollama usage.

    Delivers usage stats as a single sandboxed embed iframe (Open WebUI
    v0.11+). The embed is separate from message content and status history,
    so it is invisible to the LLM, never persisted as text, and unaffected by
    other filters' status lines.
    """

    class Valves(BaseModel):
        user_configs: str = Field(
            default="",
            description='JSON array: [{"name": "user1", "secure_session": "...", "aid": "...", "cf_clearance": "..."}]',
        )
        delay_seconds: float = Field(
            default=0.5,
            description="Delay before fetching to allow Ollama to update stats",
        )
        enabled: bool = Field(default=True, description="Enable/disable globally")
        debug_mode: bool = Field(
            default=False,
            description="Enable debug logging to console (logs structure, not message contents)",
        )

    class UserValves(BaseModel):
        visible_accounts: str = Field(
            default="all",
            description="Show only accounts, separated by commas (example: Account_Name1, Account_Name2). Use 'all' to show every account.",
        )

    def __init__(self):
        self.valves = self.Valves()
        self.toggle = True
        self.icon = (
            "https://cdn.jsdelivr.net/gh/twitter/twemoji@latest/assets/svg/2601.svg"
        )
        self._cache: Dict[str, tuple] = {}
        self._cache_ttl = 20

    def _log(self, msg: str):
        """Print debug message if debug mode is enabled."""
        if self.valves.debug_mode:
            print(f"DEBUG [filter]: {msg}")

    def _debug_header(self):
        if self.valves.debug_mode:
            print("\n========== Ollama Usage Monitor — DEBUG ==========")

    def _debug_footer(self):
        if self.valves.debug_mode:
            print("========== Ollama Usage Monitor — DEBUG END ==========\n")

    def _get_clients(self) -> List[OllamaUsageClient]:
        """Initialize clients from valve configuration."""
        clients = []
        if self.valves.user_configs:
            try:
                configs = json.loads(self.valves.user_configs)
                for cfg in configs:
                    if cfg.get("enabled", True):
                        clients.append(
                            OllamaUsageClient(
                                name=cfg.get("name", ""),
                                secure_session=cfg.get("secure_session", ""),
                                aid=cfg.get("aid", ""),
                                cf_clearance=cfg.get("cf_clearance"),
                                debug=self.valves.debug_mode,
                            )
                        )
            except (json.JSONDecodeError, TypeError) as e:
                self._log(f"Error parsing user_configs: {e}")
        return clients

    def _apply_account_filter(
        self, clients: List[OllamaUsageClient], __user__: Optional[dict]
    ) -> List[OllamaUsageClient]:
        """Apply the per-user visible_accounts whitelist. 'all' = show all."""
        raw = "all"
        if __user__ and isinstance(__user__, dict):
            uv = __user__.get("valves")
            if uv is not None:
                raw = getattr(uv, "visible_accounts", "all") or "all"

        if raw.strip().lower() == "all" or not raw.strip():
            self._log("visible_accounts is 'all' / empty -> showing all accounts")
            return clients

        wanted = [n.strip() for n in raw.split(",") if n.strip()]
        wanted_set = set(wanted)
        filtered = [c for c in clients if c.name in wanted_set]
        self._log(
            f"visible_accounts={wanted} -> showing "
            f"{[c.name for c in filtered]} of {[c.name for c in clients]}"
        )
        return filtered

    async def outlet(
        self,
        body: dict,
        __user__: Optional[dict] = None,
        __event_emitter__: Optional[Callable] = None,
        **kwargs,
    ) -> dict:
        """Emit Ollama Cloud usage as a sandboxed embed iframe on the response."""
        self._debug_header()

        if not self.valves.enabled:
            self._log("Filter disabled via valves, skipping")
            self._debug_footer()
            return body

        if not __event_emitter__:
            # Without an emitter (e.g. direct API calls) there is no UI to show
            # the embed in, and we never write into message content.
            self._log("No __event_emitter__ available, skipping")
            self._debug_footer()
            return body

        clients = self._get_clients()
        clients = self._apply_account_filter(clients, __user__)
        if not clients:
            self._log("No accounts to show (none configured or all filtered out)")
            self._debug_footer()
            return body

        await asyncio.sleep(self.valves.delay_seconds)

        current_time = time.time()
        accounts = []

        for i, client in enumerate(clients):
            name = client.name if client.name else f"user{i+1}"

            cache_key = f"{client.secure_session}:{client.aid}"
            cached = self._cache.get(cache_key)
            if cached and (current_time - cached[1] < self._cache_ttl):
                data = cached[0]
                remaining = self._cache_ttl - (current_time - cached[1])
                self._log(
                    f"[{name}] using cached data (TTL remaining: {remaining:.1f}s)"
                )
            else:
                data = client.fetch_usage()
                self._cache[cache_key] = (data, current_time)
                self._log(f"[{name}] fetched fresh data")

            accounts.append({"name": name, "data": data})

        try:
            await __event_emitter__(
                {"type": "embeds", "data": {"embeds": [_build_embed(accounts)]}}
            )
            self._log(f"Delivered embed with {len(accounts)} account(s)")
        except Exception as e:
            # Never let a UI-emit failure break the response pipeline.
            self._log(f"embed emit failed: {type(e).__name__}: {str(e)[:100]}")

        self._debug_footer()
        return body
